/bin/bash -lc "python - <<'PY'
import json
from pathlib import Path
items = json.loads(Path('out/decisions.json').read_text())
assert len(items) == 6
assert len({x['id'] for x in items}) == 6
for x in items:
    assert set(x) == {'id', 'decision', 'skill_id', 'reason'}
    assert x['decision'] in {'recommend', 'covered', 'unnecessary', 'clarify', 'no_match'}
    assert len(x['reason']) < 180
    if x['decision'] == 'recommend':
        assert (Path('catalog') / x['skill_id'] / 'SKILL.md').is_file()
    else:
        assert x['skill_id'] is None
print('Validated 6 decisions.')
PY"

